"""Import keyframe data from the locally decompiled official 1.20.2 client."""
from pathlib import Path
import re
import zipfile

root = Path(__file__).resolve().parents[1]
source = (root / 'tmp/warden-model120/ers.java').read_text()
names = ['EMERGE', 'DIG', 'ROAR', 'SNIFF', 'ATTACK', 'SONIC']
out = ['package com.mod.htgt6.minecraft1202.Module.Client.Modern;',
       '/** Original 1.20.2 keyframes; generated by tools/port_warden_animations120.py. */',
       'final class WardenKeyframes120 {']
total = 0
for name, line in zip(names, [s for s in source.splitlines() if 'public static final erm' in s]):
    channels = re.findall(r'\.a\("([^"]+)", new erl\(erl.d.([abc]), new ern\[\]\{(.*?)\}\)\)', line)
    assert channels
    out.append('    static final WardenAnimation120.Channel[] '+name+' = {')
    for bone, target, keys in channels:
        frames = re.findall(r'new ern\(([\d.]+)f, ero.([ab])\((.*?)\), erl.b.([ab])\)', keys)
        assert frames and len(frames) == keys.count('new ern(')
        values = []
        for time, helper, xyz, interpolation in frames:
            nums = re.findall(r'\(float\)(-?[\d.]+)f', xyz)
            assert len(nums) == 3 and target in 'ab'
            values.extend([time+'F']+[v+'F' for v in nums]+['1F' if interpolation == 'b' else '0F'])
        out.append('        new WardenAnimation120.Channel("'+bone+'", '+('true' if target == 'b' else 'false')+', new float[]{'+','.join(values)+'}),')
        total += len(frames)
    out.append('    };')
out.append('}')
dest = root/'src/main/java/com/mod/htgt6/minecraft1202/Module/Client/Modern/WardenKeyframes120.java'
dest.write_text('\n'.join(out)+'\n', encoding='utf-8')
with zipfile.ZipFile(root/'tmp/minecraft-1.20.2-client.jar') as jar:
    for name in ['warden','warden_bioluminescent_layer','warden_heart','warden_pulsating_spots_1','warden_pulsating_spots_2']:
        data = jar.read('assets/minecraft/textures/entity/warden/'+name+'.png')
        (root/'src/main/resources/assets/htgt6/textures/entity/warden'/ (name+'.png')).write_bytes(data)
print('Imported six animations:', total, 'keyframes; five original textures')
